// grabient kY4mpDazO-mUuu_fuLqXU49dvVP6
// https://grabient.com/kY4mpDazO-mUuu_fuLqXU49dvVP6?style=papercut
// the papercut, the palette cut into sheets of paper, as GLSL ES 3.00, the WebGL page's shaders
//
// Each frame is two passes: the field (a ramp along the angle, a few hills and hollows, two waves bending them), its
// slope and its curvature at every fourth pixel each way, kept as exact floats; then each pixel's sheets shaded from
// the four samples about it, each sheet's drop shadow, contact shadow, lit cut and face painted over the one below
// from the field's own distance to its cut, and a half-level dither. A frame sets only the hills, the waves' phases
// and the light. The uniforms' values are the page's.

// ==== Pass 1: the field ==== target: ceil((W - 1) / 4) + 3 x ceil((H - 1) / 4) + 3 texels (a sample every fourth pixel each way, one past each edge), RGBA32UI (each float's bits), one triangle over it (vertex ids 0 to 2, no attributes) | inputs: the ramp, the waves and the hills (uniforms)
#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}
#version 300 es
precision highp float;
precision highp int;
uniform vec2 uSize;
uniform float uD;
uniform vec2 uRamp;
uniform vec4 uWarp;
uniform vec4 uPhase;
uniform int uBumps;
uniform vec4 uBump[6];
out uvec4 o;

vec4 field(vec2 q) {
  float s1 = uWarp.y * q.y + uPhase.x;
  float s2 = uWarp.y * q.x + uPhase.y;
  float u = uWarp.w * (q.x + q.y) + uPhase.z;
  float v = uWarp.w * (q.x - q.y) + uPhase.w;
  float su = sin(u);
  float sv = sin(v);
  vec2 w = vec2(q.x + uWarp.x * sin(s1) + uWarp.z * sv, q.y + uWarp.x * sin(s2) + uWarp.z * su);
  float c1 = uWarp.x * uWarp.y * cos(s1);
  float c2 = uWarp.x * uWarp.y * cos(s2);
  float cu = uWarp.z * uWarp.w * cos(u);
  float cv = uWarp.z * uWarp.w * cos(v);
  mat2 J = mat2(1.0 + cv, c2 + cu, c1 - cv, 1.0 + cu);
  float f = w.x * uRamp.x + w.y * uRamp.y;
  vec2 g = uRamp;
  vec3 h = vec3(0.0);
  for (int i = 0; i < 6; i++) {
    if (i >= uBumps) break;
    vec4 B = uBump[i];
    vec2 e = w - B.xy;
    float s = dot(e, e) * B.z;
    if (s < 1.0) {
      float k = 1.0 - s;
      float k2 = k * k;
      f += B.w * k2 * k;
      float c = -6.0 * B.w * k2 * B.z;
      g += c * e;
      float qq = 24.0 * B.w * B.z * B.z * k;
      h += vec3(c + qq * e.x * e.x, qq * e.x * e.y, c + qq * e.y * e.y);
    }
  }
  vec2 G = vec2(g.x * J[0][0] + g.y * J[0][1], g.x * J[1][0] + g.y * J[1][1]);
  mat2 H = mat2(h.x, h.y, h.y, h.z);
  mat2 Q = transpose(J) * H * J;
  float g2 = dot(G, G);
  float kn = g2 > 0.0 ? dot(G, Q * G) / g2 : 0.5 * (Q[0][0] + Q[1][1]);
  float tr = Q[0][0] + Q[1][1];
  float round = tr * tr > 0.0 ? clamp(8.0 * (Q[0][0] * Q[1][1] - Q[0][1] * Q[1][0]) / (tr * tr), 0.0, 1.0) : 0.0;
  return vec4(f, G, kn * round);
}
void main() {
  vec2 p = (floor(gl_FragCoord.xy) - 1.0) * 4.0 + 0.5;
  o = floatBitsToUint(field((p - 0.5 * uSize) / uD));
}

// ==== Pass 2: the sheets ==== target: the canvas, W x H, the same triangle | inputs: Pass 1 (texelFetch), the levels, the sheets' colors and shadows and the light (uniforms)
#version 300 es
precision highp float;
precision highp int;
uniform vec2 uSize;
uniform float uD;
uniform vec2 uLight;
uniform int uSheets;
uniform float uLevel[24];
uniform vec3 uFace[24];
uniform vec3 uWallC[24];
uniform vec3 uShade[24];
uniform vec4 uSheet[24];
uniform float uReach[24];
uniform vec2 uMisc;
uniform highp usampler2D uField;
out vec4 o;

float phi(float x) {
  float t = clamp((x + 2.54) * 0.19685039, 0.0, 1.0);
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

vec3 sheet(vec3 c, int k, float f, float gl, float kap, float nl, float wn, float toPx) {
  vec4 S = uSheet[k];
  float rise = uLevel[k - 1] - f;
  float d = -rise * toPx;
  float ds = d + S.y * nl;
  float size = 1.0;
  float csize = 1.0;
  if (rise > 0.0) {
    float disc = gl * gl + 2.0 * kap * rise;
    float ak = abs(kap);
    if (ak * 16.0 * S.y > gl * uD) {
      float top = gl / ak * uD;
      float R = (disc >= 0.0 ? sqrt(disc) : -sqrt(-disc)) / ak * uD;
      float e = kap < 0.0 ? 1.0 : -1.0;
      d = -e * (top - R);
      ds = -e * (sqrt(top * top - 2.0 * e * top * S.y * nl + S.y * S.y) - R);
      if (e > 0.0) {
        float R2 = max(0.0, R) * R;
        size = 1.0 - exp(-0.5 * R2 * S.x * S.x);
        csize = 1.0 - exp(-0.5 * R2 * S.w * S.w);
      }
    } else {
      d = -uD * (disc >= 0.0 ? (2.0 * rise) / (gl + sqrt(disc)) : (gl + sqrt(-disc)) / -kap);
      ds = d + S.y * nl;
    }
  }
  float x = ds * S.x;
  if (x > -2.54) c += (uShade[k] - c) * (S.z * phi(x) * size);
  float xc = d * S.w;
  if (xc > -2.54) c += (uShade[k] - c) * (uMisc.x * phi(xc) * csize);
  if (d + max(0.0, wn) > -0.5) {
    c += (uWallC[k] - c) * clamp(d + 0.5, 0.0, 1.0);
    c += (uFace[k] - c) * clamp(d + wn + 0.5, 0.0, 1.0);
  }
  return c;
}

vec4 shade(vec4 F, vec2 px) {
  float f = F.x;
  vec2 G = F.yz;
  int top = uSheets - 1;
  int b = 0;
  for (int i = 0; i < 23; i++) {
    if (i >= top) break;
    if (f >= uLevel[i]) b++;
  }
  float gl = max(1e-9, length(G));
  float toPx = uD / gl;
  float kap = F.w;
  float nl = dot(G, uLight) / gl;
  float wn = uMisc.y * nl;
  vec3 c = uFace[0];
  bool own = false;
  if (b > 0) {
    if ((f - uLevel[b - 1]) * toPx + wn >= 0.5) c = uFace[b];
    else {
      c = uFace[b - 1];
      own = true;
    }
  }
  if (own) c = sheet(c, b, f, gl, kap, nl, wn, toPx);
  if (b < top) c = sheet(c, b + 1, f, gl, kap, nl, wn, toPx);
  if (b + 1 < top && (uLevel[b + 1] - f) * toPx < uReach[b + 2]) c = sheet(c, b + 2, f, gl, kap, nl, wn, toPx);
  float a = 0.06711056 * px.x + 0.00583715 * px.y;
  float n = fract(52.9829189 * fract(a)) - 0.5;
  return vec4(c + n / 255.0, 1.0);
}
void main() {
  vec2 px = vec2(gl_FragCoord.x - 0.5, uSize.y - gl_FragCoord.y - 0.5);
  vec2 t = px / 4.0 + 1.0;
  ivec2 i = ivec2(t);
  vec2 a = t - vec2(i);
  vec4 f00 = uintBitsToFloat(texelFetch(uField, i, 0));
  vec4 f10 = uintBitsToFloat(texelFetch(uField, i + ivec2(1, 0), 0));
  vec4 f01 = uintBitsToFloat(texelFetch(uField, i + ivec2(0, 1), 0));
  vec4 f11 = uintBitsToFloat(texelFetch(uField, i + ivec2(1, 1), 0));
  o = shade(mix(mix(f00, f10, a.x), mix(f01, f11, a.x), a.y), px);
}

